'use client';

import {useEffect, useRef, useState, type ReactNode} from 'react';
import {Icon, ChartLine, Retry, TableView} from '@/components/glaze/icon';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/glaze/data';
import {cn} from '@/lib/glaze/utils';
import {Button} from '@/components/glaze/ui/button';
import {SegmentedControl, SegmentedControlItem} from '@/components/glaze/ui/segmented-control';
import {Skeleton} from '@/components/glaze/ui/skeleton';
import {Status} from '@/components/glaze/ui/status';
import {
  ChartContainer, ChartDataTable, ChartLegend, ChartSwatch, ChartTooltip, ChartTooltipContent, ChartTooltipRow, WithChart,
  chartLegendVariants, seriesClass, seriesTone, useChart, useElementDirection, useElementWidth, useOptionalChart, useRovingPoints,
  type ChartConfig, type ChartContextValue, type ChartDataTableColumn, type ChartDataTableProps, type ChartDataTableRow,
  type ChartLegendProps, type ChartSeriesConfig, type ChartStatus, type ChartTooltipProps,
} from '@/components/glaze/ui/chart-parts';
import {BarChart, ChartPlot, LineChart, type BarChartProps, type ChartPlotProps, type ChartScale, type LineChartProps} from '@/components/glaze/ui/chart-plot';
import {formatCompact, linearPath, monotonePath, niceScale, numberAt, stepPath, unitFormat, type ChartRow, type ChartUnit, type Curve} from '@/components/glaze/ui/chart-scale';
import {Sparkline, StatusBar, sparklineVariants, statusBarVariants, type SparklineProps, type StatusBarBucket, type StatusBarProps} from '@/components/glaze/ui/chart-strip';

// Glaze's chart: one component, <Chart type="line" | "bar" | "sparkline" | "status">, with its frame (title, loading,
// error, retry, empty), legend, tooltip and data table built in. Plain SVG, no chart library; the parts stay exported
// for a chart that needs its own layout.
//
// Black and white first. A series is ink, a second ink at 60%, more repeat dashed; colour goes only on a series that is
// a status, and on the status bar's bad buckets. The tooltip is Tooltip's ink chip. Axis labels are the 12px caption in
// text-2, in tabular figures, and the axis, tooltip and table share one unit picked from the largest value.
//
// frame="card" is the chart as a widget, in the card: the grey shell, the white panel holding the title and the plot,
// and the legend on the shell's footer row. plain has no chrome, for a chart beside a number or in a card of its own. none
// is the bare drawing (the sparkline's default).
//
// The detail from the job: a chart holds its exact height in every state, and its loading shape is its own type (bars
// for bar, a line for line, capsules for status), still, in the skeleton's grey, so a dashboard of eight charts never
// jumps as they load and each is recognisable before its data lands. Every chart keeps its data table, empty ones
// too. The files: chart-scale.ts, chart-parts.tsx, chart-plot.tsx, chart-strip.tsx and this one. Import from here.

type ChartFrameStyle = 'card' | 'plain';
type Shape = 'bar' | 'line' | 'status' | 'sparkline';

type ChartFrameProps = Omit<React.ComponentProps<'section'>, 'title'> & {
  /** card: the shell, the panel and the footer row. plain: no chrome. */
  frame?: ChartFrameStyle;
  title: ReactNode;
  description?: ReactNode;
  /** Controls at the top end: a range Select, a ghost icon Button. */
  actions?: ReactNode;
  /** The legend: on the shell's footer row in a card, under the plot in plain. */
  footer?: ReactNode;
  /** px. The body's height in every state. */
  height?: number;
  loading?: boolean;
  /** What failed. Shows the error state instead of the chart. */
  error?: ReactNode;
  onRetry?: () => void;
  /** True while a retry runs. */
  retrying?: boolean;
  /** No data: the sentence to show. */
  empty?: ReactNode;
  /** The data as a visible table. Adds a Chart / Table switch. */
  table?: ReactNode;
  /** The loading shape: the chart's own type. */
  shape?: Shape;
  /** The data is still arriving: a running Live status in the header. */
  live?: boolean;
};

const silhouette = [38, 52, 44, 66, 58, 72, 49, 61, 80, 68, 74, 90];

/** Each type's loading shape, still, in the skeleton's grey. */
function Silhouette({shape}: {shape: Shape}) {
  // value-ok: each silhouette bar's height is a share of the body, from a fixed list, so it can only live inline.
  if (shape === 'bar') return <>{silhouette.map((h, i) => <Skeleton key={i} className="flex-1 rounded-b-none" style={{height: `${h}%`}}/>)}</>;
  if (shape === 'status') return <span aria-hidden className="flex h-(--control-sm) w-full gap-0.5 self-center">{Array.from({length: 30}, (_, i) => <Skeleton key={i} className="h-full min-w-1 flex-1 rounded-pill"/>)}</span>;
  const points = silhouette.map((h, i) => `${(i / (silhouette.length - 1)) * 100},${100 - h}`).join(' ');
  return <svg aria-hidden viewBox="0 0 100 100" preserveAspectRatio="none" className="size-full overflow-visible text-field">
    <polyline points={points} fill="none" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" strokeWidth={shape === 'line' ? 4 : 2} className="stroke-current forced-colors:stroke-[GrayText]"/>
  </svg>;
}

function ChartFrame({title, description, actions, footer, height = 200, loading, error, onRetry, retrying, empty, table, shape = 'bar', frame = 'card', live, className, children, ...props}: ChartFrameProps) {
  const [view, setView] = useState<'chart' | 'table'>('chart');
  const state = loading ? 'loading' : error ? 'error' : empty ? 'empty' : 'ready';
  // Retry unmounts with the error; if it had focus, focus moves to the chart's title, never the page.
  const titleRef = useRef<HTMLHeadingElement>(null);
  const retryFocused = useRef(false);
  useEffect(() => {
    if (state === 'error' || !retryFocused.current) return;
    retryFocused.current = false;
    if (!document.activeElement || document.activeElement === document.body) titleRef.current?.focus();
  }, [state]);
  const showTable = table && view === 'table' && state === 'ready';
  const card = frame === 'card';

  const header = <header data-slot="chart-frame-header" className={cn('flex min-w-0 items-start justify-between gap-3', card ? 'p-3' : 'pb-3')}>
    <div className="flex min-w-0 flex-col gap-0.5">
      <h3 ref={titleRef} tabIndex={-1} data-slot="chart-frame-title" className="min-w-0 truncate type-label text-text-1 outline-none">{title}</h3>
      {description && <p data-slot="chart-frame-description" className="type-body-sm text-text-2">{description}</p>}
    </div>
    {(actions || table || live) && <div data-slot="chart-frame-actions" className="-my-0.5 flex shrink-0 items-center gap-2">
      {live && <Status status="running" size="sm">Live</Status>}
      {actions}
      {table && <SegmentedControl size="sm" aria-label="View" value={view} onValueChange={next => setView(next as 'chart' | 'table')}>
        <SegmentedControlItem value="chart" aria-label="Chart"><Icon icon={ChartLine}/></SegmentedControlItem>
        <SegmentedControlItem value="table" aria-label="Table"><Icon icon={TableView}/></SegmentedControlItem>
      </SegmentedControl>}
    </div>}
  </header>;

  const body = <div data-slot="chart-frame-plot" className={cn('min-w-0', card && (showTable ? 'border-t border-line-faint' : 'px-3 pb-3'))}>
    {/* value-ok: the body holds the chart's height in px in every state, so nothing jumps; it can only live inline. */}
    <div data-slot="chart-frame-body" className="relative min-w-0" style={showTable ? undefined : {height}}>
      {state === 'loading' && <div data-slot="chart-frame-loading" data-shape={shape} className="flex h-full items-end gap-1">
        <span className="sr-only">Loading {typeof title === 'string' ? title : 'chart'}</span>
        <Silhouette shape={shape}/>
      </div>}
      {/* Top-left, where the chart would start, in a body that keeps its height. */}
      {state === 'error' && <div role="status" className="flex h-full flex-col items-start gap-2">
        <Status status="fail">{error}</Status>
        {onRetry && <Button size="sm" variant="secondary" pending={!!retrying} pendingLabel="Retrying" onFocus={() => { retryFocused.current = true; }} onBlur={event => { if (event.relatedTarget) retryFocused.current = false; }} onClick={onRetry}><Icon icon={Retry}/>Retry</Button>}
      </div>}
      {state === 'empty' && <div className="relative h-full type-body-sm text-text-2">
        {empty}
        <span aria-hidden className="absolute inset-x-0 bottom-6 h-px bg-line"/>
      </div>}
      {state === 'ready' && (showTable ? table : children)}
    </div>
  </div>;

  // The footer keeps its room in every state, so the legend landing never moves what is below.
  const foot = footer && !showTable ? <div data-slot="chart-frame-footer" aria-hidden={state !== 'ready' || undefined} inert={state !== 'ready' || undefined} className={cn(card ? 'shell-foot ps-0.5' : 'pt-2', state !== 'ready' && 'invisible')}>{footer}</div> : null;

  return <section
    data-slot="chart-frame"
    data-state={state}
    data-frame={frame}
    aria-busy={loading || undefined}
    className={cn('flex min-w-0 flex-col text-text-1', card && 'shell forced-colors:border-[CanvasText]', className)}
    {...props}
  >
    {card
      ? <div data-slot="chart-frame-panel" className="panel flex min-w-0 flex-col overflow-hidden forced-colors:border-[CanvasText]">{header}{body}</div>
      : <>{header}{body}</>}
    {foot}
  </section>;
}

// ---------- Chart ----------

type ChartCommon = {
  /** The chart's name: the frame title, the point group and the data table's caption. */
  label: string;
  /** Shown above the chart; the label by default. */
  title?: ReactNode;
  description?: ReactNode;
  actions?: ReactNode;
  /** card: shell, panel and footer row. plain: no chrome. none: the bare drawing (the sparkline's default). */
  frame?: 'card' | 'plain' | 'none';
  /** The data is still arriving: a running Live status in the header. */
  live?: boolean;
  /** px. The body holds it in every state. */
  height?: number;
  loading?: boolean;
  /** What failed. Shows the error state, with Retry when onRetry is set. */
  error?: ReactNode;
  onRetry?: () => void;
  retrying?: boolean;
  /** The sentence for no data, shown when data is empty. */
  empty?: ReactNode;
  /** Axis, tooltip and table share one unit from the largest value. */
  unit?: ChartUnit;
  valueFormat?: (value: number) => string;
  className?: string;
};

type CartesianChartProps = ChartCommon & {
  type: 'line' | 'bar';
  data: ChartRow[];
  /** The field that names each row on the x axis. */
  xKey: string;
  config: ChartConfig;
  series?: string[];
  xFormat?: (value: unknown, index: number) => string;
  /** The legend on the footer row. On with more than one series. */
  legend?: boolean;
  /** A Chart / Table switch in the header. */
  table?: boolean;
  /** Series switched off at first. */
  defaultHidden?: string[];
  curve?: Curve;
  area?: boolean;
  zero?: boolean;
  stacked?: boolean;
};

type SparklineChartProps = ChartCommon & Omit<SparklineProps, 'label' | 'className' | 'size' | 'valueFormat'> & {
  type: 'sparkline';
  size?: SparklineProps['size'];
};

type StatusChartProps = ChartCommon & Omit<StatusBarProps, 'label' | 'className' | 'size' | 'data' | 'unit'> & {
  type: 'status';
  data: StatusBarBucket[];
  size?: StatusBarProps['size'];
  /** The noun for a bucket's count, singular and plural: ['run', 'runs']. */
  noun?: [string, string];
};

type ChartProps = CartesianChartProps | SparklineChartProps | StatusChartProps;

/** One chart: line, bar, sparkline or status buckets, with its frame states, legend, tooltip and table. */
function Chart(props: ChartProps) {
  const {type, label, title, description, actions, height, loading, error, onRetry, retrying, empty, unit, className, live} = props;
  const frame = props.frame ?? (type === 'sparkline' ? 'none' : 'card');
  let values: number[];
  if (props.type === 'line' || props.type === 'bar') {
    const keys = props.series ?? Object.keys(props.config);
    values = [];
    for (const row of props.data as ChartRow[]) for (const key of keys) if (key !== props.xKey) { const v = numberAt(row, key); if (v !== null) values.push(v); }
  } else if (props.type === 'sparkline') values = props.data.filter((v): v is number => typeof v === 'number');
  else values = (props.data as StatusBarBucket[]).map(b => b.count);
  const format = props.valueFormat ?? unitFormat(unit, values);
  const isEmpty = !loading && !error && props.data.length === 0;
  // An empty chart still has its table, one row that says so; the sentence on screen is hidden from a reader, so it is heard once.
  const emptyText = empty ?? CHART_EMPTY;
  const emptyColumns = props.type === 'line' || props.type === 'bar'
    ? (props.series ?? Object.keys(props.config).filter(k => k !== props.xKey)).map(key => ({key, label: props.config[key]?.label ?? key}))
    : props.type === 'status' ? [{key: 'count', label: 'Count'}, {key: 'status', label: 'Status'}] : [{key: 'v', label}];
  const emptyState = isEmpty
    ? <><span aria-hidden>{emptyText}</span><ChartDataTable caption={label} rowHeader={props.type === 'line' || props.type === 'bar' ? props.config[props.xKey]?.label ?? 'Date' : props.type === 'status' ? 'Bucket' : 'Point'} columns={emptyColumns} rows={[]} empty={emptyText}/></>
    : undefined;
  const bodyHeight = height ?? (type === 'status' ? (props.size === 'sm' ? 16 : props.size === 'lg' ? 32 : 26) + 24 : type === 'sparkline' ? 26 : 200);

  if (type === 'line' || type === 'bar') {
    const {data, xKey, config, series, xFormat, curve, area, zero, stacked, defaultHidden} = props as CartesianChartProps;
    const shown = series ?? Object.keys(config).filter(k => k !== xKey);
    const showLegend = (props as CartesianChartProps).legend ?? shown.length > 1;
    const chart = type === 'line'
      ? <LineChart data={data} xKey={xKey} series={series} label={label} height={bodyHeight} curve={curve} area={area} zero={zero} xFormat={xFormat} valueFormat={format} empty={empty}/>
      : <BarChart data={data} xKey={xKey} series={series} label={label} height={bodyHeight} stacked={stacked} xFormat={xFormat} valueFormat={format} empty={empty}/>;
    let tableNode: ReactNode = null;
    if ((props as CartesianChartProps).table) {
      const f = format ?? formatCompact;
      tableNode = <ChartDataTable visible caption={label} rowHeader={config[xKey]?.label ?? 'Date'} columns={shown.map(key => ({key, label: config[key]?.label ?? key}))}
        rows={data.map((row, i) => ({key: String(i), label: (xFormat ?? (v => String(v)))(row[xKey], i), values: Object.fromEntries(shown.map(key => { const v = numberAt(row, key); return [key, v === null ? EMPTY_VALUE : f(v)]; }))}))}/>;
    }
    return <ChartContainer config={config} xKey={xKey} defaultHidden={defaultHidden} className="min-w-0">
      <ChartFrame title={title ?? label} description={description} actions={actions} footer={showLegend ? <ChartLegend series={series}/> : null} height={bodyHeight} loading={loading} error={error} onRetry={onRetry} retrying={retrying} empty={emptyState} table={tableNode} shape={type} frame={frame === 'card' ? 'card' : 'plain'} live={live} data-chart-type={type} className={className}>{chart}</ChartFrame>
    </ChartContainer>;
  }

  let chart: ReactNode = null;
  if (props.type === 'sparkline') {
    const {data, status, variant, area, end, labels, interactive, size} = props;
    chart = <Sparkline data={data} label={label} status={status} variant={variant} area={area} end={end} labels={labels} interactive={interactive} size={size} valueFormat={format} className={frame === 'none' ? className : 'w-full'}/>;
  } else if (props.type === 'status') {
    const {data, noun, range, onBucketClick, size} = props;
    chart = <StatusBar data={data} label={label} unit={noun} range={range} onBucketClick={onBucketClick} size={size} className={frame === 'none' ? className : undefined}/>;
  }
  if (frame === 'none') {
    if (loading) return <span data-slot="chart-frame-loading" data-shape={type} aria-busy className={cn('inline-flex', type === 'sparkline' ? 'h-(--control-sm) w-24' : 'h-(--control-sm) w-full', className)}><span className="sr-only">Loading {label}</span><Silhouette shape={type}/></span>;
    return chart;
  }
  return <ChartFrame title={title ?? label} description={description} actions={actions} height={bodyHeight} loading={loading} error={error} onRetry={onRetry} retrying={retrying} empty={emptyState} shape={type} frame={frame} live={live} data-chart-type={type} className={className}>{chart}</ChartFrame>;
}

export {
  Chart, unitFormat,
  ChartContainer, ChartPlot, ChartSwatch, WithChart, useChart, useOptionalChart, useElementWidth, useElementDirection, useRovingPoints,
  seriesTone, seriesClass, niceScale, formatCompact, numberAt,
  ChartTooltip, ChartTooltipContent, ChartTooltipRow,
  ChartDataTable,
  ChartLegend, chartLegendVariants,
  LineChart, monotonePath, linearPath, stepPath,
  BarChart,
  Sparkline, sparklineVariants,
  StatusBar, statusBarVariants,
  ChartFrame,
  type ChartProps, type ChartUnit, type ChartConfig, type ChartSeriesConfig, type ChartStatus, type ChartContextValue, type ChartRow, type ChartScale, type ChartPlotProps,
  type ChartTooltipProps, type ChartDataTableProps, type ChartDataTableColumn, type ChartDataTableRow, type ChartLegendProps,
  type LineChartProps, type Curve, type BarChartProps, type SparklineProps, type StatusBarProps, type StatusBarBucket, type ChartFrameProps,
};

import {countUnitFor, durationUnitFor, fixed} from '@/lib/glaze/data';

// Glaze's chart arithmetic, apart from React: nice ticks, the axis formats, reading a value off a row and the
// line paths. chart.tsx re-exports all of it; this file is where it lives.

type ChartRow = Record<string, unknown>;

type ChartUnit = 'duration' | 'count';

type Curve = 'linear' | 'monotone' | 'step';

type Point = {x: number; y: number};

/** Ticks at 1, 2, 2.5 or 5 times a power of ten, covering [min, max]. A reversed extent is read the right way round. */
function niceScale(min: number, max: number, count = 4) {
  if (!Number.isFinite(min) || !Number.isFinite(max)) { min = 0; max = 1; }
  if (min > max) [min, max] = [max, min];
  count = Math.max(1, Math.round(count) || 1);
  if (min === max) { max = min === 0 ? 1 : min + Math.abs(min); }
  const raw = (max - min) / count;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const n = raw / magnitude;
  const step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * magnitude;
  const lo = Math.floor(min / step) * step;
  const hi = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let t = lo; t <= hi + step / 2; t += step) ticks.push(Number(t.toPrecision(12)));
  return {min: lo, max: hi, ticks};
}

const compact = new Intl.NumberFormat('en-US', {notation: 'compact', maximumFractionDigits: 1});

/** 1.2k, 3.4M. The default axis format. */
function formatCompact(value: number) {
  return compact.format(value);
}

/** One unit for a whole axis, picked from the largest value: ms, s, min, h for durations; none, k, M for counts. */
function unitFormat(unit: ChartUnit | undefined, values: number[]): ((v: number) => string) | undefined {
  if (!unit) return undefined;
  // The unit is picked from the largest value as it will show, so 59,999ms is a minute, not 60.0s. A tick
  // takes one decimal under 10 and none above, decided after rounding, and zero never reads "-0".
  const {unit: name, size} = unit === 'duration' ? durationUnitFor(values) : countUnitFor(values);
  const plain = new Intl.NumberFormat('en-US', {maximumFractionDigits: 0, signDisplay: 'negative'});
  return v => {
    const x = v / size;
    if (size === 1) return `${unit === 'duration' ? fixed(x, 0) : plain.format(x)}${name}`;
    return `${fixed(x, Math.abs(Number(x.toFixed(1))) >= 10 ? 0 : 1)}${name}`;
  };
}

/** A row's value for a series, or null when it is missing or not a finite number. */
function numberAt(row: ChartRow | undefined, key: string): number | null {
  const v = row?.[key];
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

/** Monotone cubic (Fritsch–Carlson): smooth, but never overshoots a value the data does not have. */
function monotonePath(points: Point[]) {
  if (points.length < 3) return linearPath(points);
  const n = points.length;
  const dx: number[] = [], slope: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    dx.push(points[i + 1].x - points[i].x);
    slope.push((points[i + 1].y - points[i].y) / (dx[i] || 1));
  }
  const tangent = [slope[0]];
  for (let i = 1; i < n - 1; i++) tangent.push(slope[i - 1] * slope[i] <= 0 ? 0 : (slope[i - 1] + slope[i]) / 2);
  tangent.push(slope[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (slope[i] === 0) { tangent[i] = 0; tangent[i + 1] = 0; continue; }
    const a = tangent[i] / slope[i], b = tangent[i + 1] / slope[i], h = a * a + b * b;
    if (h > 9) { const t = 3 / Math.sqrt(h); tangent[i] = t * a * slope[i]; tangent[i + 1] = t * b * slope[i]; }
  }
  let d = `M${points[0].x},${points[0].y}`;
  for (let i = 0; i < n - 1; i++) {
    const p = points[i], q = points[i + 1], h = dx[i] / 3;
    d += `C${p.x + h},${p.y + tangent[i] * h},${q.x - h},${q.y - tangent[i + 1] * h},${q.x},${q.y}`;
  }
  return d;
}

function linearPath(points: Point[]) {
  return points.map((p, i) => `${i ? 'L' : 'M'}${p.x},${p.y}`).join('');
}

function stepPath(points: Point[]) {
  return points.map((p, i) => i ? `H${(points[i - 1].x + p.x) / 2}V${p.y}` : `M${p.x},${p.y}`).join('') + (points.length ? `H${points[points.length - 1].x}` : '');
}

export {
  niceScale, formatCompact, unitFormat, numberAt, monotonePath, linearPath, stepPath,
  type ChartRow, type ChartUnit, type Curve, type Point,
};

'use client';

import {createContext, memo, useCallback, useContext, useId, useLayoutEffect, useMemo, useRef, useState, type ReactNode} from 'react';
import {createPortal} from 'react-dom';
import {cva, type VariantProps} from 'class-variance-authority';
import {useGlazePortal} from '@/lib/glaze/portal';
import {useDomDirection} from '@/lib/glaze/direction';
import {CHART_EMPTY, EMPTY_VALUE, useScrollTabStop} from '@/lib/glaze/data';
import {cn} from '@/lib/glaze/utils';
import {tooltipPopupClass} from '@/components/glaze/ui/tooltip';

// The pieces every Glaze chart shares: the config and legend state (ChartContainer), each series' tone and swatch,
// the measuring and roving-focus hooks, the tooltip, the data table and the legend. chart.tsx re-exports all of it.
//
// Colour in a chart follows Glaze's one rule: colour means status. A series is ink. A second is ink at 60% (text-2's
// step, 5.5:1 on paper, so it still clears the 3:1 a line needs). Past two, the steps repeat drawn differently, a dashed
// line and a hollow bar, because ink at 45% sits barely over 3:1 and a third grey would be a guess. Green, amber and coral
// go only on a series that is a status (status: 'ok', 'warn' or 'fail': passed, retried and failed runs), never to
// tell two ordinary series apart. Every series draws in currentColor, set by one text class, so the line, the bar,
// the swatch and the legend can never disagree.
//
// The tooltip is Tooltip's look, the one inverse chip in Glaze: ink with the inverse label, the tag corner, no shadow.
// Ink series turn to the inverse ink on it, so a swatch never vanishes into the chip.

type ChartStatus = 'ok' | 'warn' | 'fail';

type ChartSeriesConfig = {
  /** The series name, in the legend, the tooltip, the table and every point's accessible name. */
  label: string;
  /** A series that is an outcome (passed, retried, failed runs) takes that status's colour. Nothing else takes colour. */
  status?: ChartStatus;
  /** Draw it dashed (a line) or hollow (a bar), a cue that needs no hue. The third and later ink series get it anyway. */
  dashed?: boolean;
};

type ChartConfig = Record<string, ChartSeriesConfig>;

type ChartContextValue = {
  config: ChartConfig;
  keys: string[];
  /** Series switched off in the legend. */
  hidden: ReadonlySet<string>;
  toggle: (key: string) => void;
  /** The series the legend points at; the others dim. */
  highlight: string | null;
  setHighlight: (key: string | null) => void;
};

const ChartContext = createContext<ChartContextValue | null>(null);

/** The config, hidden series and highlight of the nearest ChartContainer. Throws outside one. */
function useChart() {
  const context = useContext(ChartContext);
  if (!context) throw new Error('useChart must be used within a <ChartContainer/>');
  return context;
}

function useOptionalChart() {
  return useContext(ChartContext);
}

type ChartContainerProps = React.ComponentProps<'div'> & {
  config: ChartConfig;
  /** The config's x field, when it has one (it names the table's first column): left out of the series. */
  xKey?: string;
  /** Series that start switched off. */
  defaultHidden?: string[];
};

/** Holds the config and the legend state for the charts and legend inside it. */
function ChartContainer({config, xKey, defaultHidden, className, children, ...props}: ChartContainerProps) {
  const [hidden, setHidden] = useState<ReadonlySet<string>>(() => new Set(defaultHidden));
  const [highlight, setHighlight] = useState<string | null>(null);
  const toggle = useCallback((key: string) => setHidden(prev => {
    const next = new Set(prev);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  }), []);
  const value = useMemo(() => ({config, keys: Object.keys(config).filter(k => k !== xKey), hidden, toggle, highlight, setHighlight}), [config, xKey, hidden, toggle, highlight]);
  return <ChartContext.Provider value={value}>
    <div data-slot="chart" className={cn('flex w-full min-w-0 flex-col', className)} {...props}>{children}</div>
  </ChartContext.Provider>;
}

/** Wraps a chart in its own container when it was given a config and is not inside one. */
function WithChart({config, xKey, children}: {config?: ChartConfig; xKey?: string; children: ReactNode}) {
  const context = useOptionalChart();
  if (context || !config) return children;
  return <ChartContainer config={config} xKey={xKey}>{children}</ChartContainer>;
}

// ---------- Tone ----------

type Tone = 'ink' | 'ink-2' | ChartStatus;

/** The text class that sets a tone's currentColor, on paper and on the ink tooltip chip. */
const toneClass: Record<Tone, string> = {ink: 'text-text-1', 'ink-2': 'text-text-2', ok: 'text-ok', warn: 'text-warn', fail: 'text-fail'};
const toneOnInk: Record<Tone, string> = {ink: 'text-text-inverse', 'ink-2': 'text-text-inverse/60', ok: 'text-ok', warn: 'text-warn', fail: 'text-fail'};

/**
 * A series' tone and whether it is dashed: ink, then ink at 60%, then both again dashed. Status series keep their
 * colour. keys is the series in order (the container's, which leaves out the x field).
 */
function seriesTone(config: ChartConfig, key: string, keys: string[] = Object.keys(config)): {tone: Tone; dashed: boolean} {
  const {status, dashed = false} = config[key] ?? {};
  if (status) return {tone: status, dashed};
  const inkIndex = Math.max(0, keys.filter(k => !config[k]?.status).indexOf(key));
  return {tone: inkIndex % 2 === 0 ? 'ink' : 'ink-2', dashed: dashed || inkIndex >= 2};
}

/** The class that colours what draws a series: its tone as currentColor. */
function seriesClass(config: ChartConfig, key: string, onInk = false, keys?: string[]) {
  const {tone} = seriesTone(config, key, keys);
  return (onInk ? toneOnInk : toneClass)[tone];
}

/**
 * The series' key: a short 8px line in its tone, the plot's own stroke in little, dashed for a dashed series. Never a
 * dot. Off (switched away in the legend) drops it to text-3; the name beside it is struck through.
 */
function ChartSwatch({config, series, onInk, off, className}: {config: ChartConfig; series: string; onInk?: boolean; off?: boolean; className?: string}) {
  const keys = useOptionalChart()?.keys;
  const {dashed} = seriesTone(config, series, keys);
  return <svg
    data-slot="chart-swatch"
    aria-hidden
    focusable="false"
    width={8}
    height={8}
    viewBox="0 0 8 8"
    className={cn('shrink-0', off ? 'text-text-3' : seriesClass(config, series, onInk, keys), className)}
  >
    <line x1={0} y1={4} x2={8} y2={4} strokeWidth={2} strokeDasharray={dashed ? '3 2' : undefined} className="stroke-current forced-colors:stroke-[CanvasText]"/>
  </svg>;
}

// ---------- Hooks ----------

/** The width of an element, kept current with a ResizeObserver. 0 until it mounts. */
function useElementWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setWidth(el.clientWidth);
    const observer = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  return [ref, width] as const;
}

/** The element's own reading direction, so a chart under dir="rtl" mirrors. */
function useElementDirection(ref: React.RefObject<HTMLElement | null>): 'ltr' | 'rtl' {
  return useDomDirection(ref);
}

/**
 * Roving focus over a row of points: one point in the tab order; arrows, Home and End move it, Shift moves seven. In a
 * right-to-left chart the side arrows follow the screen.
 */
function useRovingPoints(count: number, onMove: (index: number, el: HTMLElement | null) => void) {
  const [current, setCurrent] = useState(count - 1);
  const refs = useRef<(HTMLElement | null)[]>([]);
  const safe = Math.min(Math.max(current, 0), count - 1);
  const move = (index: number) => {
    const next = Math.min(Math.max(index, 0), count - 1);
    setCurrent(next);
    const el = refs.current[next];
    el?.focus();
    onMove(next, el ?? null);
  };
  const onKeyDown = (event: React.KeyboardEvent, index: number) => {
    const step = event.shiftKey ? 7 : 1;
    const back = getComputedStyle(event.currentTarget).direction === 'rtl' ? -1 : 1;
    const keys: Record<string, number> = {ArrowRight: index + step * back, ArrowDown: index + step, ArrowLeft: index - step * back, ArrowUp: index - step, Home: 0, End: count - 1};
    if (!(event.key in keys)) return;
    event.preventDefault();
    move(keys[event.key]);
  };
  return {
    current: safe,
    setCurrent,
    onKeyDown,
    tabIndex: (index: number) => (index === safe ? 0 : -1),
    ref: (index: number) => (el: HTMLElement | null) => { refs.current[index] = el; },
  };
}

// ---------- Tooltip ----------

const GAP = 8;
const EDGE = 8;

type ChartTooltipProps = {
  /** The point to point at, in viewport pixels. null hides the tooltip. */
  anchor: {x: number; y: number} | null;
  children?: ReactNode;
  className?: string;
};

/** The chip at a point: Tooltip's ink chip, above the point, flipped under it near the top, kept 8px inside the viewport. */
function ChartTooltip({anchor, children, className}: ChartTooltipProps) {
  const container = useGlazePortal();
  const ref = useRef<HTMLDivElement>(null);
  const [place, setPlace] = useState<{left: number; top: number} | null>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!anchor || !el) { setPlace(null); return; }
    const {width, height} = el.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const top = anchor.y - GAP - height < EDGE ? anchor.y + GAP : anchor.y - GAP - height;
    const left = Math.min(Math.max(anchor.x - width / 2, EDGE), vw - width - EDGE);
    setPlace({left, top});
  }, [anchor, children]);

  if (!anchor || container === null) return null;
  const tooltip = <div
    ref={ref}
    data-slot="chart-tooltip"
    aria-hidden
    className={cn(tooltipPopupClass, 'pointer-events-none fixed z-(--z-overlay) min-w-32 flex-col items-stretch gap-1 py-1.5', !place && 'invisible', className)}
    // value-ok: the chip follows the pointer, so its place is measured each time and can only live inline.
    style={{left: place?.left ?? 0, top: place?.top ?? 0}}
  >{children}</div>;
  return container ? createPortal(tooltip, container) : tooltip;
}

/** A title (the x value) over the rows. */
function ChartTooltipContent({title, children, className}: {title?: ReactNode; children?: ReactNode; className?: string}) {
  return <div data-slot="chart-tooltip-content" className={cn('flex flex-col gap-1', className)}>
    {title && <div data-slot="chart-tooltip-title" className="type-label-sm text-text-inverse/70">{title}</div>}
    {children}
  </div>;
}

/** One series on the chip: its swatch, its name and its value, the value at the end in tabular figures. */
function ChartTooltipRow({indicator, label, value, className}: {indicator?: ReactNode; label: ReactNode; value: ReactNode; className?: string}) {
  return <div data-slot="chart-tooltip-row" className={cn('flex items-center gap-2 type-label-sm', className)}>
    {indicator}
    <span className="min-w-0 flex-1 truncate text-text-inverse/70">{label}</span>
    <span className="data text-text-inverse">{value}</span>
  </div>;
}

// ---------- Data table ----------

type ChartDataTableColumn = {key: string; label: ReactNode};
type ChartDataTableRow = {key: string; label: ReactNode; values: Record<string, ReactNode>};

type ChartDataTableProps = {
  /** The table's name. Usually the chart's label. */
  caption: ReactNode;
  /** The one row a table with no rows shows, so an empty chart still says so. */
  empty?: ReactNode;
  /** The head of the first column, which names each row. */
  rowHeader?: ReactNode;
  columns: ChartDataTableColumn[];
  rows: ChartDataTableRow[];
  /** Show the table instead of keeping it for screen readers only. */
  visible?: boolean;
  className?: string;
};

const thClass = 'sticky top-0 h-8 border-b border-line-faint bg-paper px-3 align-middle type-label-sm text-text-2';
const tdClass = 'h-8 px-3 align-middle type-label-sm';

/** Every chart's data as a table: hidden for a screen reader, or visible behind the frame's Chart / Table switch. */
const ChartDataTable = memo(function ChartDataTable({caption, rowHeader = 'Date', columns, rows, empty = CHART_EMPTY, visible, className}: ChartDataTableProps) {
  const box = useRef<HTMLDivElement>(null);
  const tab = useScrollTabStop(box, !!visible);
  const captionId = useId();
  const named = tab === 0 ? (typeof caption === 'string' ? {'aria-label': caption} : {'aria-labelledby': captionId}) : {};
  return <div
    ref={box}
    data-slot="chart-data-table"
    data-visible={visible || undefined}
    tabIndex={tab}
    role={tab === 0 ? 'region' : undefined}
    {...named}
    className={cn(visible ? 'max-h-(--popup-max) overflow-auto focus-visible:focus-ring-inset' : 'sr-only', className)}
  >
    <table className="w-full border-separate border-spacing-0 text-start">
      <caption id={captionId} className="sr-only">{caption}</caption>
      <thead>
        <tr>
          <th scope="col" className={cn(thClass, 'text-start')}>{rowHeader}</th>
          {columns.map(column => <th key={column.key} scope="col" className={cn(thClass, 'text-end')}>{column.label}</th>)}
        </tr>
      </thead>
      <tbody className="[&>tr:not(:last-child)>*]:border-b [&>tr:not(:last-child)>*]:border-line-faint">
        {rows.length === 0 && <tr data-slot="chart-data-table-empty">
          <td colSpan={columns.length + 1} className={cn(tdClass, 'text-start text-text-2')}>{empty}</td>
        </tr>}
        {rows.map(row => <tr key={row.key}>
          <th scope="row" className={cn(tdClass, 'text-start font-normal whitespace-nowrap text-text-2')}>{row.label}</th>
          {columns.map(column => <td key={column.key} className={cn(tdClass, 'data text-end text-text-1')}>{row.values[column.key] ?? EMPTY_VALUE}</td>)}
        </tr>)}
      </tbody>
    </table>
  </div>;
});

// ---------- Legend ----------

const chartLegendVariants = cva('flex min-w-0', {
  variants: {
    layout: {
      row: 'flex-wrap items-center gap-0.5',
      column: 'flex-col gap-0.5',
    },
  },
  defaultVariants: {layout: 'row'},
});

type ChartLegendProps = Omit<React.ComponentProps<'ul'>, 'children'> & VariantProps<typeof chartLegendVariants> & {
  /** Series to list. Defaults to every key in the config. */
  series?: string[];
  /** A value after each name: the latest reading, a total. */
  values?: Record<string, ReactNode>;
  /** Let people switch series off. Off makes the legend a plain key. */
  toggle?: boolean;
};

/** The key: each series' swatch and name as a 26px pill that switches it off and on, and points at it on hover. */
function ChartLegend({series, values, toggle = true, layout = 'row', className, ...props}: ChartLegendProps) {
  const {config, keys, hidden, toggle: flip, highlight, setHighlight} = useChart();
  const list = series ?? keys;
  return <ul data-slot="chart-legend" data-layout={layout} className={cn(chartLegendVariants({layout}), className)} {...props}>
    {list.map(key => {
      const off = hidden.has(key);
      const dim = highlight !== null && highlight !== key;
      const body = <>
        <ChartSwatch config={config} series={key} off={off}/>
        <span className={cn('min-w-0 truncate', off ? 'text-text-2 line-through decoration-1' : 'text-text-1')}>{config[key]?.label ?? key}</span>
        {values?.[key] !== undefined && <span className="data ms-auto ps-2 text-text-2">{values[key]}</span>}
      </>;
      const item = 'flex h-(--control-sm) w-full min-w-0 items-center gap-1.5 rounded-pill px-2 type-label-sm';
      return <li key={key} className={cn('min-w-0 transition-opacity duration-(--dur-state)', dim && 'opacity-(--stale)', layout === 'column' && 'w-full')}>
        {toggle
          ? <button
              type="button"
              data-slot="chart-legend-item"
              aria-pressed={!off}
              onClick={() => flip(key)}
              onPointerEnter={() => !off && setHighlight(key)}
              onPointerLeave={() => setHighlight(null)}
              onFocus={() => !off && setHighlight(key)}
              onBlur={() => setHighlight(null)}
              onKeyDown={event => { if (event.key === 'Escape') setHighlight(null); }}
              className={cn(item, 'transition-colors duration-(--dur-state) ease-out hover:bg-hover')}
            >{body}</button>
          : <span data-slot="chart-legend-item" className={item}>{body}</span>}
      </li>;
    })}
  </ul>;
}

export {
  ChartContainer, WithChart, useChart, useOptionalChart, useElementWidth, useElementDirection, useRovingPoints,
  seriesTone, seriesClass, ChartSwatch,
  ChartTooltip, ChartTooltipContent, ChartTooltipRow,
  ChartDataTable,
  ChartLegend, chartLegendVariants,
  type ChartConfig, type ChartSeriesConfig, type ChartStatus, type ChartContextValue, type Tone,
  type ChartTooltipProps, type ChartDataTableProps, type ChartDataTableColumn, type ChartDataTableRow, type ChartLegendProps,
};

'use client';

import {useEffect, useRef, useState, type ReactNode} from 'react';
import {CHART_EMPTY, EMPTY_VALUE, cssNumber} from '@/lib/glaze/data';
import {cn} from '@/lib/glaze/utils';
import {
  ChartDataTable, ChartSwatch, ChartTooltip, ChartTooltipContent, ChartTooltipRow, WithChart,
  seriesClass, seriesTone, useChart, useElementDirection, useElementWidth, useRovingPoints, type ChartConfig,
} from '@/components/glaze/ui/chart-parts';
import {formatCompact, linearPath, monotonePath, niceScale, numberAt, stepPath, type ChartRow, type Curve, type Point} from '@/components/glaze/ui/chart-scale';

// ChartPlot, the cartesian frame line and bar share, and the line and bar charts drawn in it. chart.tsx re-exports all
// of it.
//
// The frame is quiet so the series reads first: gridlines in the faint row rule, the zero line one step darker, tick
// labels in the 12px caption in text-2 and tabular figures, x labels that thin out to fit. Each x value is one
// focusable column (roving tabindex, arrow keys) with a crosshair on a line chart or a hover band on a bar chart, the
// tooltip chip and a screen-reader table. In a right-to-left chart x runs right to left and the y axis sits on the right.

type ChartScale = {
  width: number;
  height: number;
  plot: {left: number; right: number; top: number; bottom: number};
  /** Centre of the x slot for a row index. */
  x: (index: number) => number;
  /** Pixel y for a value. */
  y: (value: number) => number;
  /** Width of one x slot. */
  band: number;
  /** The row under the pointer or focus. */
  active: number | null;
  rtl: boolean;
};

type ChartPlotProps = {
  data: ChartRow[];
  /** The field that names each row on the x axis. */
  xKey: string;
  /** The series drawn, in order. */
  series: string[];
  config: ChartConfig;
  /** 'point' puts the first and last rows on the plot's edges (lines); 'band' gives each row a slot (bars). */
  mode: 'point' | 'band';
  /** Smallest and largest value to fit. The scale rounds out to nice ticks. */
  extent: [number, number];
  height: number;
  /** The chart's name, for the point group and the table caption. */
  label: string;
  xFormat: (value: unknown, index: number) => string;
  valueFormat: (value: number) => string;
  /** Value text in the tooltip, table and accessible names. Defaults to valueFormat. */
  tooltipFormat?: (value: number) => string;
  /** A last tooltip row, like a stacked total. */
  tooltipFooter?: (row: ChartRow) => ReactNode;
  children: (scale: ChartScale) => ReactNode;
  /** Drawn over the series for the active row: the squares on lines. */
  overlay?: (scale: ChartScale) => ReactNode;
  empty?: ReactNode;
  className?: string;
};

const X_LABEL_ROOM = 24;
const TICK_CHAR = 7;
const X_LABEL_MIN = 72;
const TICK_SPACE = 28;

/** The frame line, bar and custom x/y charts share: axes, grid, keyboard points, tooltip and table. */
function ChartPlot({data, xKey, series, config, mode, extent, height, label, xFormat, valueFormat, tooltipFormat = valueFormat, tooltipFooter, children, overlay, empty = CHART_EMPTY, className}: ChartPlotProps) {
  const [ref, width] = useElementWidth<HTMLDivElement>();
  const rtl = useElementDirection(ref) === 'rtl';
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const n = data.length;

  // One y interval per TICK_SPACE of plot height, four at most: a short chart (88px) gets three labels, not five
  // crowded 16px apart.
  const scale = niceScale(extent[0], extent[1], Math.min(4, Math.max(1, Math.floor((height - X_LABEL_ROOM) / TICK_SPACE))));
  const tickLabels = scale.ticks.map(valueFormat);
  const gap = width ? cssNumber(ref.current, '--space-2', 8) : 8;
  const axisRoom = Math.max(...tickLabels.map(t => t.length)) * TICK_CHAR + gap;
  const endRoom = mode === 'point' ? gap : 0;
  const plot = rtl
    ? {left: endRoom, right: Math.max(endRoom + 1, width - axisRoom), top: gap, bottom: height - X_LABEL_ROOM}
    : {left: axisRoom, right: Math.max(axisRoom + 1, width - endRoom), top: gap, bottom: height - X_LABEL_ROOM};
  const plotWidth = plot.right - plot.left;
  const band = mode === 'band' ? plotWidth / Math.max(n, 1) : plotWidth / Math.max(n - 1, 1);
  const origin = rtl ? plot.right : plot.left;
  const forward = rtl ? -1 : 1;
  const x = (i: number) => mode === 'band' ? origin + forward * band * (i + 0.5) : n === 1 ? plot.left + plotWidth / 2 : origin + forward * band * i;
  const y = (v: number) => plot.bottom - ((v - scale.min) / (scale.max - scale.min)) * (plot.bottom - plot.top);
  const s: ChartScale = {width, height, plot, x, y, band, active, rtl};

  const anchorFor = (index: number) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return null;
    const values = series.map(key => numberAt(data[index], key)).filter((v): v is number => v !== null);
    const top = values.length ? y(Math.max(...values)) : plot.top;
    return {x: rect.left + x(index), y: rect.top + Math.min(top, plot.bottom)};
  };
  const show = (index: number) => { setActive(index); setAnchor(anchorFor(index)); };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(n, index => show(index));

  // A tooltip at the pointer would drift from its point on scroll, so it closes.
  useEffect(() => {
    if (active === null) return;
    const close = () => { if (!ref.current?.contains(document.activeElement)) hide(); };
    window.addEventListener('scroll', close, {capture: true, passive: true});
    return () => window.removeEventListener('scroll', close, {capture: true});
  }, [active, ref]);

  const xLabelEvery = Math.max(1, Math.ceil(n / Math.max(1, Math.floor(plotWidth / X_LABEL_MIN))));
  const pointName = (index: number) => {
    const row = data[index];
    const values = series.map(key => {
      const v = numberAt(row, key);
      return `${config[key]?.label ?? key} ${v === null ? 'no data' : tooltipFormat(v)}`;
    });
    return `${xFormat(row?.[xKey], index)}: ${values.join(', ')}`;
  };

  const table = <ChartDataTable
    caption={label}
    empty={empty}
    rowHeader={config[xKey]?.label ?? 'Date'}
    columns={series.map(key => ({key, label: config[key]?.label ?? key}))}
    rows={data.map((row, i) => ({key: String(i), label: xFormat(row[xKey], i), values: Object.fromEntries(series.map(key => {
      const v = numberAt(row, key);
      return [key, v === null ? EMPTY_VALUE : tooltipFormat(v)];
    }))}))}
  />;

  // value-ok: the plot's height is the chart's, in px, so the drawing and its box agree; it can only live inline.
  const box = {height};

  // No rows: the sentence, the table still there saying the same, and the baseline, so the chart keeps its shape.
  if (n === 0) {
    return <div ref={ref} data-slot="chart-plot" className={cn('relative type-body-sm text-text-2', className)} style={box}>
      {table}
      <span aria-hidden className="block pt-2">{empty}</span>
      <span aria-hidden className="absolute inset-x-0 bottom-6 h-px bg-line"/>
    </div>;
  }

  return <div ref={ref} data-slot="chart-plot" className={cn('relative w-full min-w-0', className)} style={box}>
    {table}
    {width > 0 && <>
      {/* Coordinates are physical, mirrored above for right to left, so the drawing itself stays left to right. */}
      <svg ref={svgRef} aria-hidden direction="ltr" width={width} height={height} className="block overflow-visible">
        {mode === 'band' && active !== null && <rect x={x(active) - band / 2} y={plot.top} width={band} height={plot.bottom - plot.top} rx={4} className="fill-hover"/>}
        {scale.ticks.map((tick, i) => <g key={tick}>
          <line x1={plot.left} x2={plot.right} y1={y(tick)} y2={y(tick)} strokeWidth={1} className={tick === 0 ? 'stroke-line' : 'stroke-line-faint'} shapeRendering="crispEdges"/>
          <text x={rtl ? plot.right + gap : plot.left - gap} y={y(tick)} dy="0.32em" textAnchor={rtl ? 'start' : 'end'} className="fill-text-2 type-caption">{tickLabels[i]}</text>
        </g>)}
        {data.map((row, i) => {
          if ((n - 1 - i) % xLabelEvery !== 0) return null;
          // The last label hangs inward from the edge, so a label within one label's room of it would overlap it.
          if (mode === 'point' && i !== n - 1 && Math.abs(x(n - 1) - x(i)) < X_LABEL_MIN) return null;
          const first = rtl ? 'end' : 'start', last = rtl ? 'start' : 'end';
          const at = mode === 'point' && n > 1 ? (i === 0 ? first : i === n - 1 ? last : 'middle') : 'middle';
          return <text key={i} x={x(i)} y={height - 6} textAnchor={at} className="fill-text-2 type-caption">{xFormat(row[xKey], i)}</text>;
        })}
        {mode === 'point' && active !== null && <line x1={x(active)} x2={x(active)} y1={plot.top} y2={plot.bottom} strokeWidth={1} className="stroke-line-strong" shapeRendering="crispEdges"/>}
        {children(s)}
        {overlay?.(s)}
      </svg>
      <div
        role="group"
        aria-label={label}
        aria-roledescription="chart"
        className="absolute flex"
        // value-ok: the hit areas cover the plot, whose edges are measured, so they can only live inline.
        style={{left: mode === 'band' || n === 1 ? plot.left : plot.left - band / 2, top: plot.top, width: mode === 'band' || n === 1 ? plotWidth : plotWidth + band, height: plot.bottom - plot.top}}
        onPointerLeave={() => { if (!ref.current?.contains(document.activeElement)) hide(); }}
      >
        {data.map((_, i) => <button
          key={i}
          ref={roving.ref(i)}
          type="button"
          tabIndex={roving.tabIndex(i)}
          aria-label={pointName(i)}
          onPointerEnter={() => { roving.setCurrent(i); show(i); }}
          onFocus={() => { roving.setCurrent(i); show(i); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          className="h-full min-w-0 flex-1 cursor-crosshair rounded-tag focus-visible:focus-ring-inset"
        />)}
      </div>
      <ChartTooltip anchor={active !== null ? anchor : null}>
        {active !== null && <ChartTooltipContent title={xFormat(data[active]?.[xKey], active)}>
          {series.map(key => {
            const v = numberAt(data[active], key);
            return <ChartTooltipRow key={key} indicator={<ChartSwatch config={config} series={key} onInk/>} label={config[key]?.label ?? key} value={v === null ? EMPTY_VALUE : tooltipFormat(v)}/>;
          })}
          {tooltipFooter?.(data[active])}
        </ChartTooltipContent>}
      </ChartTooltip>
    </>}
  </div>;
}

// ---------- Line ----------

type LineChartProps = {
  data: ChartRow[];
  /** The field that names each row on the x axis, usually a date. */
  xKey: string;
  /** Series to draw. Defaults to every key in the config, minus those the legend hid. */
  series?: string[];
  /** Pass a config to use the chart on its own. Inside a ChartContainer it reads the container's. */
  config?: ChartConfig;
  label: string;
  /** px. */
  height?: number;
  curve?: Curve;
  /** A faint wash under the line. One series only. */
  area?: boolean;
  /** Start the y axis at zero. Turn off for values far from zero, like latency percentiles. */
  zero?: boolean;
  xFormat?: (value: unknown, index: number) => string;
  valueFormat?: (value: number) => string;
  tooltipFormat?: (value: number) => string;
  empty?: React.ReactNode;
  className?: string;
};

const paths = {linear: linearPath, monotone: monotonePath, step: stepPath};

/** Runs of consecutive points with a value. A gap in the data is a gap in the line. */
function runs(data: ChartRow[], key: string, x: (i: number) => number, y: (v: number) => number) {
  const out: Point[][] = [];
  let current: Point[] = [];
  data.forEach((row, i) => {
    const v = numberAt(row, key);
    if (v === null) { if (current.length) out.push(current); current = []; return; }
    current.push({x: x(i), y: y(v)});
  });
  if (current.length) out.push(current);
  return out;
}

/** The line's weight and dash: 1.5px, the icons' stroke, and a 4 by 3 dash for a dashed series. */
const LINE = 1.5;
const DASH = '4 3';

function LineChartPlot({data, xKey, series, label, height = 200, curve = 'monotone', area, zero = true, xFormat = v => String(v), valueFormat = formatCompact, tooltipFormat, empty, className}: Omit<LineChartProps, 'config'>) {
  const {config, keys, hidden, highlight} = useChart();
  const shown = (series ?? keys).filter(key => !hidden.has(key));
  const values = data.flatMap(row => shown.map(key => numberAt(row, key)).filter((v): v is number => v !== null));
  const extent: [number, number] = [zero ? Math.min(0, ...values) : Math.min(...values), Math.max(...values, zero ? 0 : -Infinity)];
  const toPath = paths[curve];

  return <ChartPlot
    data={data} xKey={xKey} series={shown} config={config} mode="point" extent={extent} height={height} label={label}
    xFormat={xFormat} valueFormat={valueFormat} tooltipFormat={tooltipFormat} empty={empty} className={className}
    overlay={s => s.active !== null && shown.map(key => {
      const v = numberAt(data[s.active!], key);
      if (v === null) return null;
      // The active point: a small square in the series, ringed in paper so it lifts off the line. Never a dot.
      return <rect key={key} x={s.x(s.active!) - 3.5} y={s.y(v) - 3.5} width={7} height={7} strokeWidth={2} className={cn('fill-current stroke-paper', seriesClass(config, key, false, keys))}/>;
    })}
  >
    {s => shown.map(key => {
      const {dashed} = seriesTone(config, key, keys);
      const segments = runs(data, key, s.x, s.y);
      const dim = highlight !== null && highlight !== key;
      const base = Math.min(Math.max(s.y(0), s.plot.top), s.plot.bottom);
      return <g key={key} data-slot="line-chart-series" data-series={key} className={cn(seriesClass(config, key, false, keys), 'transition-opacity duration-(--dur-state)', dim && 'opacity-(--stale)')}>
        {area && shown.length === 1 && segments.map((pts, i) => pts.length > 1 && <path
          key={`a${i}`}
          d={`${toPath(pts)}L${pts[pts.length - 1].x},${base}L${pts[0].x},${base}Z`}
          className="fill-hover stroke-none"
        />)}
        {segments.map((pts, i) => pts.length === 1
          ? <rect key={i} x={pts[0].x - 2} y={pts[0].y - 2} width={4} height={4} className="fill-current"/>
          : <path key={i} d={toPath(pts)} fill="none" strokeWidth={LINE} strokeDasharray={dashed ? DASH : undefined} strokeLinejoin="round" strokeLinecap="round" className="stroke-current forced-colors:stroke-[CanvasText]"/>)}
      </g>;
    })}
  </ChartPlot>;
}

/** Values over time. Inside a ChartContainer it shares the container's config and legend. */
function LineChart({config, ...props}: LineChartProps) {
  return <WithChart config={config} xKey={props.xKey}><LineChartPlot {...props}/></WithChart>;
}

// ---------- Bar ----------

type BarChartProps = {
  data: ChartRow[];
  xKey: string;
  series?: string[];
  config?: ChartConfig;
  label: string;
  /** px. */
  height?: number;
  /** Stack the series in each bucket instead of setting them side by side. */
  stacked?: boolean;
  /** The share of each bucket the bars fill, 0 to 1. */
  fill?: number;
  xFormat?: (value: unknown, index: number) => string;
  valueFormat?: (value: number) => string;
  tooltipFormat?: (value: number) => string;
  empty?: React.ReactNode;
  /** A total row in a stacked chart's tooltip. On when stacked. */
  total?: boolean;
  className?: string;
};

const SEGMENT_GAP = 1;
const GROUP_GAP = 2;
const BAR_RADIUS = 2;

/**
 * One bar or segment in its series' currentColor: solid, or hollow with a 1px edge for a dashed series. The value end
 * rounds 2px, the base end stays square on the axis.
 */
function Bar({x, width, y, height, up, hollow, className, ...props}: Omit<React.SVGProps<SVGPathElement>, 'x' | 'y' | 'width' | 'height'> & {x: number; width: number; y: number; height: number; up: boolean; hollow?: boolean}) {
  const r = Math.min(BAR_RADIUS, width / 2, height);
  const inset = hollow ? 0.5 : 0;
  const x0 = x + inset, x1 = x + width - inset, y0 = y + inset, y1 = y + height - inset;
  const d = up
    ? `M${x0},${y1}V${y0 + r}Q${x0},${y0} ${x0 + r},${y0}H${x1 - r}Q${x1},${y0} ${x1},${y0 + r}V${y1}Z`
    : `M${x0},${y0}V${y1 - r}Q${x0},${y1} ${x0 + r},${y1}H${x1 - r}Q${x1},${y1} ${x1},${y1 - r}V${y0}Z`;
  return <path d={d} strokeWidth={hollow ? 1 : 0} className={cn(hollow ? 'fill-paper stroke-current' : 'fill-current', 'forced-colors:fill-[CanvasText]', className)} {...props}/>;
}

function BarChartPlot({data, xKey, series, label, height = 200, stacked, fill = 0.64, xFormat = v => String(v), valueFormat = formatCompact, tooltipFormat, total = stacked, empty, className}: Omit<BarChartProps, 'config'>) {
  const {config, keys, hidden, highlight} = useChart();
  const shown = (series ?? keys).filter(key => !hidden.has(key));
  const sum = (row: ChartRow, sign: 1 | -1) => shown.reduce((acc, key) => {
    const v = numberAt(row, key) ?? 0;
    return sign > 0 ? acc + Math.max(v, 0) : acc + Math.min(v, 0);
  }, 0);
  const values = stacked ? data.flatMap(row => [sum(row, 1), sum(row, -1)]) : data.flatMap(row => shown.map(key => numberAt(row, key) ?? 0));
  const extent: [number, number] = [Math.min(0, ...values), Math.max(0, ...values)];
  const format = tooltipFormat ?? valueFormat;

  return <ChartPlot
    data={data} xKey={xKey} series={shown} config={config} mode="band" extent={extent} height={height} label={label}
    xFormat={xFormat} valueFormat={valueFormat} tooltipFormat={tooltipFormat} empty={empty} className={className}
    tooltipFooter={total && shown.length > 1 ? row => <ChartTooltipRow className="mt-0.5 border-t border-text-inverse/20 pt-1" label="Total" value={format(sum(row, 1) + sum(row, -1))}/> : undefined}
  >
    {s => {
      const width = Math.max(1, s.band * fill);
      const zero = s.y(0);
      const dimmed = (key: string) => highlight !== null && highlight !== key;
      if (stacked) {
        return data.map((row, i) => {
          let up = 0, down = 0;
          const x0 = s.x(i) - width / 2;
          // Only the outermost segment on each side rounds its value end.
          const lastUp = [...shown].reverse().find(key => (numberAt(row, key) ?? 0) > 0);
          const lastDown = [...shown].reverse().find(key => (numberAt(row, key) ?? 0) < 0);
          return <g key={i}>
            {shown.map(key => {
              const v = numberAt(row, key);
              if (!v) return null;
              const from = v > 0 ? up : down;
              const to = from + v;
              if (v > 0) up = to; else down = to;
              const top = Math.min(s.y(from), s.y(to));
              const h = Math.abs(s.y(to) - s.y(from)) - (from === 0 ? 0 : SEGMENT_GAP);
              const outer = key === (v > 0 ? lastUp : lastDown);
              return <g key={key} className={cn(seriesClass(config, key, false, keys), 'transition-opacity duration-(--dur-state)', dimmed(key) && 'opacity-(--stale)')}>
                {outer
                  ? <Bar data-series={key} x={x0} width={width} y={v > 0 ? top : top + (from === 0 ? 0 : SEGMENT_GAP)} height={Math.max(h, 1)} up={v > 0} hollow={seriesTone(config, key, keys).dashed}/>
                  : <rect data-series={key} x={x0} width={width} y={v > 0 ? top : top + (from === 0 ? 0 : SEGMENT_GAP)} height={Math.max(h, 1)} shapeRendering="crispEdges" className={seriesTone(config, key, keys).dashed ? 'fill-paper stroke-current' : 'fill-current'}/>}
              </g>;
            })}
          </g>;
        });
      }
      const each = (width - GROUP_GAP * (shown.length - 1)) / Math.max(shown.length, 1);
      return data.map((row, i) => <g key={i}>
        {shown.map((key, j) => {
          const v = numberAt(row, key);
          if (v === null || v === 0) return null;
          return <g key={key} className={cn(seriesClass(config, key, false, keys), 'transition-opacity duration-(--dur-state)', dimmed(key) && 'opacity-(--stale)')}>
            <Bar
              data-series={key}
              // The first series leads from the start side: the right in a right-to-left chart.
              x={s.x(i) - width / 2 + (s.rtl ? shown.length - 1 - j : j) * (each + GROUP_GAP)}
              width={Math.max(each, 1)}
              y={Math.min(s.y(v), zero)}
              height={Math.max(Math.abs(zero - s.y(v)), 1)}
              up={v >= 0}
              hollow={seriesTone(config, key, keys).dashed}
            />
          </g>;
        })}
      </g>);
    }}
  </ChartPlot>;
}

/** Counts per bucket, grouped or stacked. Inside a ChartContainer it shares the container's legend. */
function BarChart({config, ...props}: BarChartProps) {
  return <WithChart config={config} xKey={props.xKey}><BarChartPlot {...props}/></WithChart>;
}

export {
  ChartPlot, LineChart, BarChart,
  type ChartScale, type ChartPlotProps, type LineChartProps, type BarChartProps,
};

'use client';

import {useRef, useState} from 'react';
import {cva, type VariantProps} from 'class-variance-authority';
import {CHART_EMPTY, EMPTY_VALUE} from '@/lib/glaze/data';
import {cn} from '@/lib/glaze/utils';
import {ChartDataTable, ChartTooltip, ChartTooltipContent, ChartTooltipRow, useElementWidth, useRovingPoints, type ChartStatus} from '@/components/glaze/ui/chart-parts';
import {StatusMark} from '@/components/glaze/ui/status';

// The two charts that are a strip rather than a plot: the sparkline beside a number and the status bar of buckets.
// chart.tsx re-exports both. Both read right to left under dir="rtl".
//
// The sparkline is ink, a 1.5px line with a small square on its last value, or ink bars; status turns it to an outcome's colour
// when the number it sits beside is one (an error rate is fail). The status bar is a row of capsules, one per bucket:
// a quiet bucket is the grey field, a bucket that went fine is ink at 45% (the 3:1 a mark needs), and only a bucket
// with trouble takes colour, amber or coral, so the eye lands on the bad day and not on thirty green ones.

// ---------- Sparkline ----------

const sparklineVariants = cva('relative inline-block min-w-0 align-middle', {
  variants: {
    size: {
      sm: 'h-4',
      default: 'h-(--control-sm)',
      lg: 'h-(--control-lg)',
    },
  },
  defaultVariants: {size: 'default'},
});

const statusText: Record<ChartStatus, string> = {ok: 'text-ok', warn: 'text-warn', fail: 'text-fail'};

type SparklineProps = Omit<React.ComponentProps<'div'>, 'children'> & VariantProps<typeof sparklineVariants> & {
  /** Values in order, oldest first. null is a gap. */
  data: (number | null)[];
  /** What the values are: "Runs per hour". Names the table and the points. */
  label: string;
  /** The values are an outcome's: an error rate is fail. Ink without it. */
  status?: ChartStatus;
  variant?: 'line' | 'bar';
  /** A faint wash under the line. */
  area?: boolean;
  /** Mark the last value with a small square. On for lines. */
  end?: boolean;
  /** Names for each point, for the table and the tooltip: dates or bucket labels. */
  labels?: string[];
  valueFormat?: (value: number) => string;
  /** Focus and hover each point, with a tooltip. */
  interactive?: boolean;
};

const VIEW_H = 100;
const PAD = 8;

/** What a screen reader hears for the values: "up from 412 to 549, low 401, high 549". */
function trendWords(values: number[], format: (v: number) => string) {
  if (!values.length) return 'no data';
  const first = values[0], last = values[values.length - 1];
  const direction = last > first ? 'up' : last < first ? 'down' : 'flat';
  return `${direction} from ${format(first)} to ${format(last)}, low ${format(Math.min(...values))}, high ${format(Math.max(...values))}`;
}

function Sparkline({data, label, status, variant = 'line', area, end = variant === 'line', labels, valueFormat = v => v.toLocaleString('en-US'), interactive, size = 'default', className, ...props}: SparklineProps) {
  const values = data.filter((v): v is number => v !== null && Number.isFinite(v));
  const n = data.length;
  const lo = variant === 'bar' ? Math.min(0, ...values) : Math.min(...values);
  const hi = Math.max(...values, lo + 1);
  const viewW = Math.max(n - 1, 1) * 10;
  const y = (v: number) => PAD + (1 - (v - lo) / (hi - lo || 1)) * (VIEW_H - PAD * 2);
  const x = (i: number) => variant === 'bar' ? (i + 0.5) * (viewW / n) : n === 1 ? viewW / 2 : (i / (n - 1)) * viewW;
  const nameAt = (i: number) => labels?.[i] ?? `Point ${i + 1}`;

  const segments: {x: number; y: number}[][] = [];
  let run: {x: number; y: number}[] = [];
  data.forEach((v, i) => {
    if (v === null || !Number.isFinite(v)) { if (run.length) segments.push(run); run = []; return; }
    run.push({x: x(i), y: y(v)});
  });
  if (run.length) segments.push(run);

  const lastIndex = data.findLastIndex(v => v !== null && Number.isFinite(v));
  const svgRef = useRef<SVGSVGElement>(null);
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const show = (i: number) => {
    setActive(i);
    const svg = svgRef.current;
    const rect = svg?.getBoundingClientRect();
    const v = data[i];
    if (!svg || !rect) return;
    const along = (x(i) / viewW) * rect.width;
    const rtl = getComputedStyle(svg).direction === 'rtl';
    setAnchor({x: rtl ? rect.right - along : rect.left + along, y: rect.top + ((v === null ? VIEW_H : y(v)) / VIEW_H) * rect.height});
  };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(n, i => show(i));
  const pct = (px: number, total: number) => `${(px / total) * 100}%`;
  const tone = status ? statusText[status] : 'text-text-1';

  // A div that stays inline-block, so it sits in a line of text; it holds the data table, so never inside a <p>.
  return <div data-slot="sparkline" data-status={status} data-variant={variant} className={cn(sparklineVariants({size}), 'w-24', tone, className)} {...props}>
    <ChartDataTable
      caption={`${label}: ${trendWords(values, valueFormat)}`}
      empty={CHART_EMPTY}
      rowHeader="Point"
      columns={[{key: 'v', label}]}
      rows={data.map((v, i) => ({key: String(i), label: nameAt(i), values: {v: v === null ? EMPTY_VALUE : valueFormat(v)}}))}
    />
    <svg ref={svgRef} aria-hidden viewBox={`0 0 ${viewW} ${VIEW_H}`} preserveAspectRatio="none" className="block size-full overflow-visible rtl:-scale-x-100">
      {variant === 'bar'
        ? data.map((v, i) => v !== null && Number.isFinite(v) && <rect key={i} x={x(i) - (viewW / n) * 0.32} width={(viewW / n) * 0.64} y={Math.min(y(v), y(0))} height={Math.max(Math.abs(y(0) - y(v)), 2)} className={cn('fill-current transition-opacity duration-(--dur-state)', active !== null && active !== i && 'opacity-(--stale)')}/>)
        : <>
            {area && segments.map((pts, i) => pts.length > 1 && <path key={`a${i}`} d={`M${pts[0].x},${VIEW_H}${pts.map(p => `L${p.x},${p.y}`).join('')}L${pts[pts.length - 1].x},${VIEW_H}Z`} className="fill-hover"/>)}
            {/* A lone point is a zero-length stroke with round caps, so the stretched viewBox cannot squash it. */}
            {segments.map((pts, i) => pts.length === 1 && <path key={`d${i}`} d={`M${pts[0].x},${pts[0].y}h0`} fill="none" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeWidth={4} className="stroke-current"/>)}
            {segments.map((pts, i) => pts.length > 1 && <path key={i} d={pts.map((p, j) => `${j ? 'L' : 'M'}${p.x},${p.y}`).join('')} fill="none" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" strokeWidth={size === 'sm' ? 1 : 1.5} className="stroke-current forced-colors:stroke-[CanvasText]"/>)}
          </>}
    </svg>
    {variant === 'line' && (active ?? (end ? lastIndex : -1)) >= 0 && (() => {
      const i = active ?? lastIndex;
      const v = data[i];
      if (v === null || !Number.isFinite(v)) return null;
      // value-ok: the square sits on the value's point, a share of the drawing, so it can only live inline.
      return <span aria-hidden data-slot="sparkline-end" className="pointer-events-none absolute size-1.5 -translate-x-1/2 -translate-y-1/2 bg-current rtl:translate-x-1/2" style={{insetInlineStart: pct(x(i), viewW), top: pct(y(v), VIEW_H)}}/>;
    })()}
    {interactive && n > 0 && <>
      <span role="group" aria-label={label} aria-roledescription="chart" className="absolute inset-0 flex" onPointerLeave={hide}>
        {data.map((v, i) => <button
          key={i}
          ref={roving.ref(i)}
          type="button"
          tabIndex={roving.tabIndex(i)}
          aria-label={`${nameAt(i)}: ${v === null ? 'no data' : valueFormat(v)}`}
          onPointerEnter={() => { roving.setCurrent(i); show(i); }}
          onFocus={() => { roving.setCurrent(i); show(i); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          className="h-full min-w-0 flex-1 rounded-tag focus-visible:focus-ring-inset"
        />)}
      </span>
      <ChartTooltip anchor={active !== null ? anchor : null}>
        {active !== null && <ChartTooltipContent title={nameAt(active)}>
          <ChartTooltipRow label={label} value={data[active] === null ? EMPTY_VALUE : valueFormat(data[active]!)}/>
        </ChartTooltipContent>}
      </ChartTooltip>
    </>}
  </div>;
}

// ---------- Status bar ----------

type StatusBarBucket = {
  /** The bucket's name: a date, an hour. Under the strip's ends and in the tooltip. */
  label: string;
  /** Runs, deploys or requests in the bucket. 0 is a quiet cell. */
  count: number;
  /** The worst outcome in the bucket. warn and fail take colour; ok stays ink. */
  status?: ChartStatus;
  /** How many of the count failed or warned, for the tooltip. */
  issues?: number;
  /** Replaces the generated text in the tooltip and the cell's name: "12 runs, 2 failed". */
  description?: string;
};

const statusBarVariants = cva('flex w-full min-w-0', {
  variants: {
    size: {
      sm: 'h-4',
      default: 'h-(--control-sm)',
      lg: 'h-(--control)',
    },
  },
  defaultVariants: {size: 'default'},
});

type StatusBarProps = Omit<React.ComponentProps<'div'>, 'children'> & VariantProps<typeof statusBarVariants> & {
  data: StatusBarBucket[];
  /** What the strip shows: "Runs, last 30 days". Names the cells and the table. */
  label: string;
  /** The noun for count, singular and plural. */
  unit?: [string, string];
  /** Text under the strip's ends. Defaults to the first and last bucket labels; false for none. */
  range?: [React.ReactNode, React.ReactNode] | false;
  /** A cell pressed with the pointer, Enter or Space: open that bucket's runs. */
  onBucketClick?: (bucket: StatusBarBucket, index: number) => void;
};

const statusWords = {ok: 'Passed', warn: 'Warning', fail: 'Failed'} as const;
const cellTone = {quiet: 'bg-field', ok: 'bg-line-strong', warn: 'bg-warn', fail: 'bg-fail'} as const;

function StatusBar({data, label, unit = ['run', 'runs'], range, onBucketClick, size = 'default', className, ...props}: StatusBarProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState<number | null>(null);
  const [anchor, setAnchor] = useState<{x: number; y: number} | null>(null);
  const cells = useRef<(HTMLElement | null)[]>([]);
  const show = (i: number, el?: HTMLElement | null) => {
    setActive(i);
    const rect = (el ?? cells.current[i])?.getBoundingClientRect();
    if (rect) setAnchor({x: rect.left + rect.width / 2, y: rect.top});
  };
  const hide = () => { setActive(null); setAnchor(null); };
  const roving = useRovingPoints(data.length, (i, el) => show(i, el));
  const noun = (n: number) => `${n.toLocaleString('en-US')} ${n === 1 ? unit[0] : unit[1]}`;
  const describe = (b: StatusBarBucket) => {
    if (b.description) return b.description;
    const parts = [b.count ? noun(b.count) : `No ${unit[1]}`];
    if (b.status && b.status !== 'ok') parts.push(`${b.issues ?? ''} ${b.status === 'fail' ? 'failed' : 'with warnings'}`.trim());
    return parts.join(', ');
  };
  const ends = range === false ? null : range ?? [data[0]?.label, data[data.length - 1]?.label];
  // Whole-pixel cells: the width shared out in integers, so no cell edge lands between pixels and blurs at 1x.
  const [stripRef, stripWidth] = useElementWidth<HTMLDivElement>();
  const gapPx = data.length > 60 ? 1 : 2;
  const avail = stripWidth - gapPx * (data.length - 1);
  const cellWidth = (i: number) => (stripWidth && avail >= data.length ? Math.floor(((i + 1) * avail) / data.length) - Math.floor((i * avail) / data.length) : undefined);

  return <div ref={ref} data-slot="status-bar" className={cn('flex w-full min-w-0 flex-col gap-1.5', className)} {...props}>
    <ChartDataTable
      caption={label}
      rowHeader="Bucket"
      columns={[{key: 'count', label: unit[1][0].toUpperCase() + unit[1].slice(1)}, {key: 'status', label: 'Status'}]}
      rows={data.map((b, i) => ({key: String(i), label: b.label, values: {count: b.count.toLocaleString('en-US'), status: b.count ? statusWords[b.status ?? 'ok'] : EMPTY_VALUE}}))}
      empty={CHART_EMPTY}
    />
    <div
      ref={stripRef}
      role="group"
      aria-label={label}
      aria-roledescription="status bar"
      className={cn(statusBarVariants({size}), data.length > 60 ? 'gap-px' : 'gap-0.5')}
      onPointerLeave={() => { if (!ref.current?.contains(document.activeElement)) hide(); }}
    >
      {data.map((b, i) => {
        const tone = b.count === 0 ? 'quiet' : b.status ?? 'ok';
        const w = cellWidth(i);
        return <button
          key={i}
          ref={el => { cells.current[i] = el; roving.ref(i)(el); }}
          type="button"
          tabIndex={roving.tabIndex(i)}
          data-slot="status-bar-cell"
          data-tone={tone}
          aria-label={`${b.label}: ${describe(b)}`}
          onPointerEnter={event => { roving.setCurrent(i); show(i, event.currentTarget); }}
          onFocus={event => { roving.setCurrent(i); show(i, event.currentTarget); }}
          onBlur={event => { if (!event.currentTarget.parentElement?.contains(event.relatedTarget as Node)) hide(); }}
          onKeyDown={event => { if (event.key === 'Escape') hide(); else roving.onKeyDown(event, i); }}
          onClick={onBucketClick && (() => onBucketClick(b, i))}
          // value-ok: each cell's whole-pixel width is measured from the strip, so it can only live inline.
          style={w ? {width: w, flex: 'none'} : undefined}
          className={cn(
            'h-full min-w-px flex-1 rounded-pill transition-opacity duration-(--dur-state) focus-sm',
            cellTone[tone],
            tone === 'quiet' ? 'forced-colors:bg-[Canvas] forced-colors:outline-1 forced-colors:-outline-offset-1' : 'forced-colors:bg-[CanvasText]',
            active !== null && active !== i && 'opacity-(--stale)',
            onBucketClick ? 'cursor-pointer' : 'cursor-default',
          )}
        />;
      })}
    </div>
    {ends && <div aria-hidden className="flex justify-between gap-4 type-caption text-text-2 data"><span>{ends[0]}</span><span>{ends[1]}</span></div>}
    <ChartTooltip anchor={active !== null ? anchor : null}>
      {active !== null && data[active] && <ChartTooltipContent title={data[active].label}>
        <ChartTooltipRow
          indicator={<StatusMark status={data[active].count === 0 ? 'idle' : data[active].status ?? 'ok'} className="h-auto text-text-inverse"/>}
          label={data[active].count ? statusWords[data[active].status ?? 'ok'] : 'Quiet'}
          value={describe(data[active])}
        />
      </ChartTooltipContent>}
    </ChartTooltip>
  </div>;
}

export {
  Sparkline, sparklineVariants,
  StatusBar, statusBarVariants,
  type SparklineProps, type StatusBarProps, type StatusBarBucket,
};
